        ORDER BY (question_id <> 'js-2022-a-q012'), review_count DESC, updated_at DESC, card_id
      ) AS rn
      FROM review_cards
      WHERE question_id IN (
  'js-2022-a-q012',
  'js-2022-b-q008')
    ) WHERE rn = 1
  );
