        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2021-b-q038'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2021-b-q038',
  'js-2021-c-q036')
