-- converge review_cards to ONE card per group (keeper's own > most-reviewed > latest).
DELETE FROM review_cards
WHERE question_id IN (
  'js-2021-a-q053',
  'js-2021-b-q054')
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2021-a-q053'), review_count DESC, updated_at DESC, card_id
      ) AS rn
      FROM review_cards
      WHERE question_id IN (
  'js-2021-a-q053',
  'js-2021-b-q054')
    ) WHERE rn = 1
  );
UPDATE review_cards SET question_id = 'js-2021-a-q053'
WHERE question_id IN (
  'js-2021-b-q054');
