-- converge review_cards to ONE card per group (keeper's own > most-reviewed > latest).
DELETE FROM review_cards
WHERE question_id IN (
  'js-2020-a-q100',
  'js-2020-b-q100',
  'js-2020-c-q100')
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2020-a-q100'), review_count DESC, updated_at DESC, card_id
      ) AS rn
      FROM review_cards
      WHERE question_id IN (
  'js-2020-a-q100',
  'js-2020-b-q100',
  'js-2020-c-q100')
    ) WHERE rn = 1
  );
UPDATE review_cards SET question_id = 'js-2020-a-q100'
