  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2020-a-q101'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2020-a-q101',
  'js-2020-c-q101')
    ) WHERE rn = 1
