        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2020-a-q043'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2020-a-q043',
  'js-2020-b-q043')
