-- converge review_cards to ONE card per group (keeper's own > most-reviewed > latest).
DELETE FROM review_cards
WHERE question_id IN (
  'js-2019-a-q017',
  'js-2019-b-q019')
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2019-a-q017'), review_count DESC, updated_at DESC, card_id
      ) AS rn
      FROM review_cards
      WHERE question_id IN (
  'js-2019-a-q017',
  'js-2019-b-q019')
    ) WHERE rn = 1
  );
