  AND role = 'primary' AND status = 'active'
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2019-a-q037'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2019-a-q037',
  'js-2019-b-q037') AND role = 'primary' AND status = 'active'
    ) WHERE rn = 1
  );
