-- converge review_cards to ONE card per group (keeper's own > most-reviewed > latest).
DELETE FROM review_cards
WHERE question_id IN (
  'js-2018-a-q037',
  'js-2018-b-q032',
  'js-2018-c-q032')
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2018-a-q037'), review_count DESC, updated_at DESC, card_id
      ) AS rn
      FROM review_cards
      WHERE question_id IN (
  'js-2018-a-q037',
  'js-2018-b-q032',
  'js-2018-c-q032')
    ) WHERE rn = 1
  );
UPDATE review_cards SET question_id = 'js-2018-a-q037'
