        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2018-a-q059'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2018-a-q059',
  'js-2018-b-q058')
