        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2017-b-q009'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2017-b-q009',
  'js-2017-c-q009')
    ) WHERE rn = 1
