-- converge review_cards to ONE card per group (keeper's own > most-reviewed > latest).
DELETE FROM review_cards
WHERE question_id IN (
  'js-2017-a-q078',
  'js-2017-b-q078',
  'js-2017-c-q078')
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2017-a-q078'), review_count DESC, updated_at DESC, card_id
      ) AS rn
      FROM review_cards
      WHERE question_id IN (
  'js-2017-a-q078',
  'js-2017-b-q078',
  'js-2017-c-q078')
    ) WHERE rn = 1
  );
UPDATE review_cards SET question_id = 'js-2017-a-q078'
WHERE question_id IN (
  'js-2017-b-q078',
  'js-2017-c-q078');
-- [js-2017-a-q095] converge question_knowledge_map (PK question_id+node):
