DELETE FROM question_knowledge_map
WHERE question_id IN (
  'js-2017-a-q095',
  'js-2017-c-q093')
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        PARTITION BY knowledge_node_id
        ORDER BY (question_id <> 'js-2017-a-q095'), weight DESC, rowid
      ) AS rn
      FROM question_knowledge_map
      WHERE question_id IN (
  'js-2017-a-q095',
  'js-2017-c-q093')
    ) WHERE rn = 1
  );
UPDATE question_knowledge_map SET question_id = 'js-2017-a-q095'
WHERE question_id IN (
  'js-2017-c-q093');

-- converge question_skill_bindings. Two invariants must hold before retargeting:
--   (a) uq_qsb_single_active_partial: at most ONE active primary binding per question
--       (index exists on freshly-migrated databases; live predates it) -- keep one
--       across the whole group, keeper's own preferred;
--   (b) UNIQUE(question_id, learning_skill_id, role): one row per (skill, role) across
--       the group, active rows preferred over inactive/needs_review.
DELETE FROM question_skill_bindings
WHERE question_id IN (
  'js-2017-a-q095',
  'js-2017-c-q093')
  AND role = 'primary' AND status = 'active'
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2017-a-q095'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2017-a-q095',
  'js-2017-c-q093') AND role = 'primary' AND status = 'active'
    ) WHERE rn = 1
  );
DELETE FROM question_skill_bindings
WHERE question_id IN (
  'js-2017-a-q095',
  'js-2017-c-q093')
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2017-a-q095'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2017-a-q095',
  'js-2017-c-q093')
    ) WHERE rn = 1
  );
UPDATE question_skill_bindings SET question_id = 'js-2017-a-q095'
WHERE question_id IN (
  'js-2017-c-q093');

