-- converge question_skill_bindings. Two invariants must hold before retargeting:
--   (a) uq_qsb_single_active_partial: at most ONE active primary binding per question
--       (index exists on freshly-migrated databases; live predates it) -- keep one
--       across the whole group, keeper's own preferred;
--   (b) UNIQUE(question_id, learning_skill_id, role): one row per (skill, role) across
--       the group, active rows preferred over inactive/needs_review.
DELETE FROM question_skill_bindings
WHERE question_id IN (
  'js-2016-a-q068',
  'js-2016-c-q065')
  AND role = 'primary' AND status = 'active'
  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2016-a-q068'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2016-a-q068',
  'js-2016-c-q065') AND role = 'primary' AND status = 'active'
    ) WHERE rn = 1
  );
