        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2016-a-q068'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2016-a-q068',
  'js-2016-c-q065')
