  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        ORDER BY (question_id <> 'js-2016-a-q113'), review_count DESC, updated_at DESC, card_id
      ) AS rn
      FROM review_cards
      WHERE question_id IN (
  'js-2016-a-q113',
  'js-2016-b-q107',
  'js-2016-c-q108')
    ) WHERE rn = 1
  );
