  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2016-a-q106'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2016-a-q106',
  'js-2016-c-q109')
    ) WHERE rn = 1
