  AND rowid NOT IN (
    SELECT rowid FROM (
      SELECT rowid, ROW_NUMBER() OVER (
        PARTITION BY learning_skill_id, role
        ORDER BY (status <> 'active'), (question_id <> 'js-2017-a-q026'), rowid
      ) AS rn
      FROM question_skill_bindings
      WHERE question_id IN (
  'js-2017-a-q026',
  'js-2017-b-q022')
    ) WHERE rn = 1
